/// Parity tests for the morning readiness gate.
///
/// Fixture is generated by `HealthTraining/scripts/parity/gen_golden_morning.py`
/// — ground truth is `scripts/morning_go.py` executed by the Python interpreter.
/// Never edit the fixture by hand; run `HealthTraining/scripts/regen_goldens.py`.
///
/// 988 golden cases across 13 case groups: `sessionDoneCases` 216 ·
/// `reducedCompliantCases` 12 · `liftFlagsCases` 51 · `trendKgWkCases` 70 ·
/// `consecutiveDoseIndexCases` 36 · `rhrCarriedOverCases` 6 ·
/// `vitalsPresentCases` 7 · `vitalsLineCases` 26 · `fmtVsCases` 47 ·
/// `prevFromStateCases` 5 · `streakCases` 29 · `bestStreakCases` 29 ·
/// `evaluateCases` 454. Each golden case is one test case, so the count
/// `swift test --filter MorningGate` prints is the golden count PLUS ONE:
/// `morningGateSourcesAvoidAmbientClockAPIs` is a non-golden source-hygiene
/// guard required by the W6 card's L1 exit criteria ("no `Date()`/
/// `TimeZone.current` in Sources (grep test)").
///
/// Verdict and condition strings are compared with plain `==` on `String` — no
/// normalisation, no trimming, no Unicode folding.

// MARK: - Ordered-object reading
//
// `liftFlags` walks the lift map in insertion order and that order decides the
// order of the flag strings it returns (six golden cases have two lifts that
// both contribute). `JSONDecoder`'s `allKeys` does NOT preserve document order
// — it reports the hash order of the parsed object — so the ordered key list is
// read from the fixture bytes with the minimal scanner below and used to
// linearise the decoded map.

private enum OrderedJSON {
    case object([(key: String, value: OrderedJSON)])
    case array([OrderedJSON])
    case scalar

    func child(_ key: String) -> OrderedJSON? {
        guard case .object(let members) = self else { return nil }
        return members.first { $0.key == key }?.value
    }

    var elements: [OrderedJSON] {
        guard case .array(let elements) = self else { return [] }
        return elements
    }

    var keyOrder: [String] {
        guard case .object(let members) = self else { return [] }
        return members.map(\.key)
    }
}

/// Structure-only JSON reader: it records object key order and array shape and
/// discards every scalar value (those come from `JSONDecoder`).
private struct OrderedJSONReader {
    private let bytes: [UInt8]
    private var index = 0

    private init(_ data: Data) { bytes = Array(data) }

    static func parse(_ data: Data) -> OrderedJSON {
        var reader = OrderedJSONReader(data)
        return reader.parseValue()
    }

    private mutating func skipWhitespace() {
        while index < bytes.count, bytes[index] == 0x20 || bytes[index] == 0x09 || bytes[index] == 0x0A || bytes[index] == 0x0D {
            index += 1
        }
    }

    private mutating func parseValue() -> OrderedJSON {
        skipWhitespace()
        guard index < bytes.count else { return .scalar }
        switch bytes[index] {
        case UInt8(ascii: "{"):
            index += 1
            var members: [(key: String, value: OrderedJSON)] = []
            skipWhitespace()
            if index < bytes.count, bytes[index] == UInt8(ascii: "}") {
                index += 1
                return .object(members)
            }
            while index < bytes.count {
                skipWhitespace()
                let key = parseString()
                skipWhitespace()
                if index < bytes.count, bytes[index] == UInt8(ascii: ":") { index += 1 }
                members.append((key, parseValue()))
                skipWhitespace()
                if index < bytes.count, bytes[index] == UInt8(ascii: ",") {
                    index += 1
                    continue
                }
                if index < bytes.count, bytes[index] == UInt8(ascii: "}") { index += 1 }
                break
            }
            return .object(members)
        case UInt8(ascii: "["):
            index += 1
            var elements: [OrderedJSON] = []
            skipWhitespace()
            if index < bytes.count, bytes[index] == UInt8(ascii: "]") {
                index += 1
                return .array(elements)
            }
            while index < bytes.count {
                elements.append(parseValue())
                skipWhitespace()
                if index < bytes.count, bytes[index] == UInt8(ascii: ",") {
                    index += 1
                    continue
                }
                if index < bytes.count, bytes[index] == UInt8(ascii: "]") { index += 1 }
                break
            }
            return .array(elements)
        case UInt8(ascii: "\""):
            _ = parseString()
            return .scalar
        default:
            while index < bytes.count, !isDelimiter(bytes[index]) { index += 1 }
            return .scalar
        }
    }

    private func isDelimiter(_ byte: UInt8) -> Bool {
        byte == UInt8(ascii: ",") || byte == UInt8(ascii: "}") || byte == UInt8(ascii: "]")
            || byte == 0x20 || byte == 0x09 || byte == 0x0A || byte == 0x0D
    }

    private mutating func parseString() -> String {
        guard index < bytes.count, bytes[index] == UInt8(ascii: "\"") else { return "" }
        index += 1
        var utf8: [UInt8] = []
        while index < bytes.count {
            let byte = bytes[index]
            if byte == UInt8(ascii: "\"") {
                index += 1
                break
            }
            if byte == UInt8(ascii: "\\") {
                index += 1
                guard index < bytes.count else { break }
                let escape = bytes[index]
                index += 1
                switch escape {
                case UInt8(ascii: "n"): utf8.append(0x0A)
                case UInt8(ascii: "t"): utf8.append(0x09)
                case UInt8(ascii: "r"): utf8.append(0x0D)
                case UInt8(ascii: "b"): utf8.append(0x08)
                case UInt8(ascii: "f"): utf8.append(0x0C)
                case UInt8(ascii: "u"):
                    var code = 0
                    for _ in 0..<4 where index < bytes.count {
                        code = code * 16 + hexValue(bytes[index])
                        index += 1
                    }
                    if let scalar = Unicode.Scalar(code) { utf8.append(contentsOf: Array(String(scalar).utf8)) }
                default: utf8.append(escape)
                }
                continue
            }
            utf8.append(byte)
            index += 1
        }
        return String(decoding: utf8, as: UTF8.self)
    }

    private func hexValue(_ byte: UInt8) -> Int {
        switch byte {
        case UInt8(ascii: "0")...UInt8(ascii: "9"): return Int(byte - UInt8(ascii: "0"))
        case UInt8(ascii: "a")...UInt8(ascii: "f"): return Int(byte - UInt8(ascii: "a")) + 10
        case UInt8(ascii: "A")...UInt8(ascii: "F"): return Int(byte - UInt8(ascii: "A")) + 10
        default: return 0
        }
    }
}

private enum MorningFixtureOrder {
    static let root: OrderedJSON = {
        guard let url = Bundle.module.url(
            forResource: "morning.golden",
            withExtension: "json",
            subdirectory: "Resources/golden"
        ), let data = try? Data(contentsOf: url) else {
            fatalError("golden fixture morning.golden.json is not in the test bundle")
        }
        return OrderedJSONReader.parse(data)
    }()

    /// Document order of the keys of the object at `path` inside each case of
    /// `group`, one entry per case, `[]` where the object is absent.
    static func keyOrders(group: String, path: [String]) -> [[String]] {
        (root.child(group)?.elements ?? []).map { element in
            var node: OrderedJSON? = element
            for step in path { node = node?.child(step) }
            return node?.keyOrder ?? []
        }
    }

    /// Linearise a decoded lift map with the fixture's own key order.
    static func lifts(_ map: [String: [LiftSessionFixture]], order: [String]) -> [LiftHistory] {
        precondition(
            Set(order) == Set(map.keys),
            "lift key order \(order) does not match the decoded lift map \(map.keys.sorted()) — fixture misalignment"
        )
        return order.map { LiftHistory(name: $0, sessions: (map[$0] ?? []).map(\.session)) }
    }
}

