struct TrendKgWkCase: GoldenCase, CustomTestStringConvertible {
    static let allowedKeys: Set<String> = ["rows", "expected"]

    let rows: [[TrendCellFixture]]
    let expected: Double?

    var trendRows: [TrendRow] {
        rows.map { cells in
            let date = cells[0].text
            switch cells[1] {
            case .number(let value): return TrendRow(date: date, weight: value)
            case .text(let value): return TrendRow(date: date, weightText: value)
            }
        }
    }

    var testDescription: String { "\(rows.count) rows -> \(expected.map { "\($0)" } ?? "nil")" }
}

