enum MorningGolden {
    private static let file = "morning.golden"

    static let sessionDoneCases = GoldenLoader.require(SessionDoneCase.self, file: file, group: "sessionDoneCases")
    static let reducedCompliantCases = GoldenLoader.require(ReducedCompliantCase.self, file: file, group: "reducedCompliantCases")
    static let trendKgWkCases = GoldenLoader.require(TrendKgWkCase.self, file: file, group: "trendKgWkCases")
    static let consecutiveDoseIndexCases = GoldenLoader.require(ConsecutiveDoseIndexCase.self, file: file, group: "consecutiveDoseIndexCases")
    static let rhrCarriedOverCases = GoldenLoader.require(RhrCarriedOverCase.self, file: file, group: "rhrCarriedOverCases")
    static let vitalsPresentCases = GoldenLoader.require(VitalsPresentCase.self, file: file, group: "vitalsPresentCases")
    static let vitalsLineCases = GoldenLoader.require(VitalsLineCase.self, file: file, group: "vitalsLineCases")
    static let fmtVsCases = GoldenLoader.require(FmtVsCase.self, file: file, group: "fmtVsCases")
    static let prevFromStateCases = GoldenLoader.require(PrevFromStateCase.self, file: file, group: "prevFromStateCases")
    static let streakCases = GoldenLoader.require(StreakCase.self, file: file, group: "streakCases")
    static let bestStreakCases = GoldenLoader.require(BestStreakCase.self, file: file, group: "bestStreakCases")

    static let liftFlagsCases: [LiftFlagsFixture] = {
        let cases = GoldenLoader.require(LiftFlagsCase.self, file: file, group: "liftFlagsCases")
        let orders = MorningFixtureOrder.keyOrders(group: "liftFlagsCases", path: ["lifts"])
        precondition(cases.count == orders.count, "liftFlagsCases/key-order count mismatch")
        return zip(cases, orders).map { golden, order in
            LiftFlagsFixture(
                lifts: MorningFixtureOrder.lifts(golden.lifts, order: order),
                reds: golden.reds,
                notes: golden.notes
            )
        }
    }()

    static let evaluateCases: [EvaluateFixture] = {
        let cases = GoldenLoader.require(EvaluateCase.self, file: file, group: "evaluateCases")
        let orders = MorningFixtureOrder.keyOrders(group: "evaluateCases", path: ["db", "lifts"])
        precondition(cases.count == orders.count, "evaluateCases/key-order count mismatch")
        return zip(cases, orders).map { golden, order in
            EvaluateFixture(
                today: golden.today,
                vitals: golden.m.vitals,
                db: golden.db.db(lifts: MorningFixtureOrder.lifts(golden.db.lifts ?? [:], order: order)),
                state: golden.state.prevState,
                dosedDates: golden.dosedDates,
                verdict: golden.verdict,
                conditions: golden.conditions,
                newState: golden.newState.newState
            )
        }
    }()
}

