@Test(arguments: MorningGolden.sessionDoneCases)
func sessionDoneMatchesPython(_ c: SessionDoneCase) {
    let got = sessionDone(
        SessionType(rawValue: c.stype),
        doneTypes: Set(c.doneTypes),
        stepOk: c.stepOk,
        longWalk: c.longWalk
    )
    #expect(got == c.expected)
}

@Test(arguments: MorningGolden.reducedCompliantCases)
func reducedCompliantMatchesPython(_ c: ReducedCompliantCase) {
    #expect(reducedCompliant(dayTypes: Set(c.dayTypes), longWalk: c.longWalk) == c.expected)
}

@Test(arguments: MorningGolden.liftFlagsCases)
func liftFlagsMatchesPython(_ c: LiftFlagsFixture) {
    let (reds, notes) = liftFlags(c.lifts)
    #expect(reds == c.reds)
    #expect(notes == c.notes)
}

/// The slope is compared on `bitPattern`, not `==`: the last operation is a
/// `pythonRound`, which preserves `-0.0`, and `0.0 == -0.0` in IEEE-754.
@Test(arguments: MorningGolden.trendKgWkCases)
func trendKgWkMatchesPython(_ c: TrendKgWkCase) throws {
    let got = try trendKgWk(c.trendRows)
    switch (got, c.expected) {
    case (nil, nil):
        break
    case (let got?, let want?):
        #expect(got.bitPattern == want.bitPattern, "got \(got), want \(want)")
    default:
        Issue.record("got \(got.map { "\($0)" } ?? "nil"), want \(c.expected.map { "\($0)" } ?? "nil")")
    }
}

@Test(arguments: MorningGolden.consecutiveDoseIndexCases)
func consecutiveDoseIndexMatchesPython(_ c: ConsecutiveDoseIndexCase) throws {
    #expect(try consecutiveDoseIndex(c.day, dosed: Set(c.dosed)) == c.expected)
}

