/// The whole verdict: the string, every condition line in order, and the state
/// written back. Strings are compared with `==` — byte-exact, no normalisation.
@Test(arguments: MorningGolden.evaluateCases)
func evaluateMatchesPython(_ c: EvaluateFixture) throws {
    let got = try evaluate(
        today: c.today,
        vitals: c.vitals,
        db: c.db,
        state: c.state,
        dosedDates: c.dosedDates
    )
    #expect(got.verdict == c.verdict, "verdict: got \"\(got.verdict)\", want \"\(c.verdict)\"")
    #expect(got.conditions.count == c.conditions.count, "condition count: got \(got.conditions), want \(c.conditions)")
    for (index, want) in c.conditions.enumerated() where index < got.conditions.count {
        #expect(got.conditions[index] == want, "condition[\(index)]: got \"\(got.conditions[index])\", want \"\(want)\"")
    }
    #expect(got.newState == c.newState)
}

/// W6 card, L1 exit: no ambient clock, locale or printf-style formatting in the
/// lane's sources. `CalendarMath` (L0) is the only sanctioned date surface and
/// `formatFixed` the only sanctioned decimal formatter — a `Date()` here would
/// make the gate answer differently on a phone in another timezone.
@Test
func morningGateSourcesAvoidAmbientClockAPIs() throws {
    let sources = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent()  // JIComputeTests
        .deletingLastPathComponent()  // Tests
        .deletingLastPathComponent()  // JICompute
        .appendingPathComponent("Sources/JICompute/MorningGate")
    let banned = ["Date()", "TimeZone.current", "Locale.current", "Calendar.current", "String(" + "format:"]
    let names = try FileManager.default.contentsOfDirectory(atPath: sources.path).sorted()
    #expect(!names.isEmpty, "no sources found at \(sources.path)")
    for name in names where name.hasSuffix(".swift") {
        let text = try String(contentsOf: sources.appendingPathComponent(name), encoding: .utf8)
        for needle in banned {
            #expect(!text.contains(needle), "\(name) uses \(needle)")
        }
    }
}
